function N({registerIndicator:h,nulls:m}){const f=(e,r)=>{const c=new Array(e.length).fill(NaN),u=new Array(r).fill(NaN);let l=0,a=0,o=0;for(let n=0;n<e.length;n++){const s=u[l];Number.isFinite(s)&&(a-=s,o-=1);const i=e[n];Number.isFinite(i)&&(a+=i,o+=1),u[l]=i,l=(l+1)%r,c[n]=o>0?a/o:NaN}return c};h({id:"oa-ac",name:"Accelerator Oscillator (AC)",category:"Oscillators",placement:"pane",inputs:[{key:"fastLength",type:"number",label:"Fast Length",default:5,min:1,max:5e3,step:1},{key:"slowLength",type:"number",label:"Slow Length",default:34,min:2,max:5e3,step:1}],plots:[{key:"ac",type:"line",title:"AC",style:{color:"#26a69a",lineWidth:2},colorBy({value:e}){return e>=0?"#26a69a":"#ef5350"}}],calc(e,r){const c=Math.max(1,Math.floor(Number(r.fastLength)||5)),u=Math.max(c+1,Math.floor(Number(r.slowLength)||34)),l=e.map(t=>(t.high+t.low)/2),a=f(l,c),o=f(l,u),n=new Array(e.length).fill(NaN);for(let t=0;t<e.length;t++)!Number.isFinite(a[t])||!Number.isFinite(o[t])||(n[t]=a[t]-o[t]);const s=f(n,5),i=new Array(e.length).fill(NaN);for(let t=0;t<e.length;t++)!Number.isFinite(n[t])||!Number.isFinite(s[t])||(i[t]=n[t]-s[t]);return{ac:m(i)}}})}export{N as default};
